## **4. Diffúzív Spiking Neural – `src/core/diffusive_snn.zig`**

```zig
const std = @import("std");
const math = std.math;

pub const SpikingNeuron = struct {
    voltage: f64,
    threshold: f64,
    decay_rate: f64,
    diffusion_coeff: f64,

    pub fn init() SpikingNeuron {
        return .{
            .voltage = 0.0,
            .threshold = 1.0,
            .decay_rate = 0.95,
            .diffusion_coeff = 0.05,
        };
    }

    pub fn step(self: *SpikingNeuron, input: f64, neighbors: []f64) bool {
        // Diffúziós hozzájárulás szomszédoktól
        var diffusion: f64 = 0.0;
        for (neighbors) |n| {
            diffusion += (n - self.voltage) * self.diffusion_coeff;
        }

        // Feszültség frissítés
        self.voltage = self.voltage * self.decay_rate + input + diffusion;

        // Spike generálás
        if (self.voltage >= self.threshold) {
            self.voltage = 0.0;  // Reset
            return true;  // Spike!
        }
        return false;
    }
};

pub const DiffusiveSNN = struct {
    neurons: []SpikingNeuron,
    connections: [][]f64,  // Neuron kapcsolatok
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, size: usize) !DiffusiveSNN {
        const neurons = try allocator.alloc(SpikingNeuron, size);
        for (neurons) |*n| {
            n.* = SpikingNeuron.init();
        }

        const connections = try allocator.alloc([]f64, size);
        for (connections) |*conn| {
            conn.* = try allocator.alloc(f64, size);
            @memset(conn.*, 0.0);
        }

        return .{
            .neurons = neurons,
            .connections = connections,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *DiffusiveSNN, inputs: []f64) ![]bool {
        const spikes = try self.allocator.alloc(bool, self.neurons.len);

        for (self.neurons, 0..) |*neuron, i| {
            var neighbors = try self.allocator.alloc(f64, self.neurons.len);
            defer self.allocator.free(neighbors);

            // Szomszédok feszültségének gyűjtése
            for (self.neurons, 0..) |n, j| {
                neighbors[j] = n.voltage * self.connections[i][j];
            }

            spikes[i] = neuron.step(inputs[i], neighbors);
        }

        return spikes;
    }

    pub fn deinit(self: *DiffusiveSNN) void {
        for (self.connections) |conn| {
            self.allocator.free(conn);
        }
        self.allocator.free(self.connections);
        self.allocator.free(self.neurons);
    }
};

// Export C API Modal számára
export fn create_snn(size: usize) *DiffusiveSNN {
    const allocator = std.heap.c_allocator;
    const snn = allocator.create(DiffusiveSNN) catch unreachable;
    snn.* = DiffusiveSNN.init(allocator, size) catch unreachable;
    return snn;
}

export fn snn_forward(snn: *DiffusiveSNN, inputs: [*]f64, len: usize) [*]bool {
    const input_slice = inputs[0..len];
    const spikes = snn.forward(input_slice) catch unreachable;
    return spikes.ptr;
}
```

