## **5. P-Adic Tokenizáló – `src/tokenizer/padic_tokenizer.zig`**

```zig
const std = @import("std");

pub const PAdicToken = struct {
    id: u32,
    depth: u8,
    embedding: [512]f32,
};

pub const PAdicTokenizer = struct {
    base: u32 = 5,  // Prím alap
    max_depth: u8 = 8,
    vocab: std.StringHashMap(PAdicToken),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) PAdicTokenizer {
        return .{
            .vocab = std.StringHashMap(PAdicToken).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn encode(self: *PAdicTokenizer, text: []const u8) ![]PAdicToken {
        var tokens = std.ArrayList(PAdicToken).init(self.allocator);

        var i: usize = 0;
        while (i < text.len) {
            var depth: u8 = 0;
            var chunk_size: usize = 1;

            // Hierarchikus chunk keresés
            while (depth < self.max_depth and i + chunk_size <= text.len) {
                const chunk = text[i..i+chunk_size];
                if (self.vocab.get(chunk)) |token| {
                    try tokens.append(token);
                    i += chunk_size;
                    break;
                }
                chunk_size *= self.base;
                depth += 1;
            }

            // Ha nincs találat, alapértelmezett token
            if (depth == self.max_depth) {
                const default_token = PAdicToken{
                    .id = @intCast(text[i]),
                    .depth = 0,
                    .embedding = undefined,
                };
                try tokens.append(default_token);
                i += 1;
            }
        }

        return tokens.toOwnedSlice();
    }

    pub fn build_vocab(self: *PAdicTokenizer, corpus: []const u8) !void {
        // P-adic fa építés a korpuszból
        var id: u32 = 256;  // ASCII után

        var depth: u8 = 1;
        while (depth <= self.max_depth) : (depth += 1) {
            const chunk_size = std.math.pow(u32, self.base, depth);

            var i: usize = 0;
            while (i + chunk_size <= corpus.len) : (i += 1) {
                const chunk = corpus[i..i+chunk_size];

                if (!self.vocab.contains(chunk)) {
                    const token = PAdicToken{
                        .id = id,
                        .depth = depth,
                        .embedding = undefined,  // Később töltjük fel
                    };
                    try self.vocab.put(try self.allocator.dupe(u8, chunk), token);
                    id += 1;
                }
            }
        }
    }
};

// C API Export
export fn create_tokenizer() *PAdicTokenizer {
    const allocator = std.heap.c_allocator;
    const tok = allocator.create(PAdicTokenizer) catch unreachable;
    tok.* = PAdicTokenizer.init(allocator);
    return tok;
}

export fn tokenizer_encode(tok: *PAdicTokenizer, text: [*]const u8, len: usize) [*]PAdicToken {
    const text_slice = text[0..len];
    const tokens = tok.encode(text_slice) catch unreachable;
    return tokens.ptr;
}
```

