## **6. 50M+ Token Kontextus – `src/context/ssi_index.zig`**

```zig
const std = @import("std");
const blake3 = @import("blake3");

pub const SSINode = struct {
    hash: [32]u8,
    position: u64,
    neighbors: []u64,  // Diffúziós szomszédok
    semantic_score: f64,
};

pub const SuccinctSemanticIndex = struct {
    tree: std.HashMap([32]u8, SSINode, std.hash_map.AutoContext([32]u8), 80),
    threshold: f64 = 0.85,
    max_tokens: u64 = 50_000_000,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) SuccinctSemanticIndex {
        return .{
            .tree = std.HashMap([32]u8, SSINode, std.hash_map.AutoContext([32]u8), 80).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn index_segment(self: *SuccinctSemanticIndex, segment: []const u8, pos: u64) !void {
        var hasher = blake3.Hasher.init();
        hasher.update(segment);
        const hash = hasher.finalize();

        // Szomszédok keresése (szemantikai hasonlóság alapján)
        var neighbors = std.ArrayList(u64).init(self.allocator);
        var iter = self.tree.iterator();
        while (iter.next()) |entry| {
            const sim = self.similarity(hash, entry.key_ptr.*);
            if (sim > self.threshold) {
                try neighbors.append(entry.value_ptr.position);
            }
        }

        const node = SSINode{
            .hash = hash,
            .position = pos,
            .neighbors = try neighbors.toOwnedSlice(),
            .semantic_score = 0.0,
        };

        try self.tree.put(hash, node);
    }

    fn similarity(self: *SuccinctSemanticIndex, h1: [32]u8, h2: [32]u8) f64 {
        _ = self;
        var matches: u32 = 0;
        for (h1, h2) |a, b| {
            matches += @popCount(~(a ^ b));
        }
        return @as(f64, @floatFromInt(matches)) / 256.0;
    }

    pub fn query(self: *SuccinctSemanticIndex, query_text: []const u8) ![]u64 {
        var hasher = blake3.Hasher.init();
        hasher.update(query_text);
        const hash = hasher.finalize();

        var results = std.ArrayList(u64).init(self.allocator);

        if (self.tree.get(hash)) |node| {
            try results.append(node.position);
            // Diffúzió: szomszédok hozzáadása
            for (node.neighbors) |n_pos| {
                try results.append(n_pos);
            }
        }

        return results.toOwnedSlice();
    }
};
```

