## **7. Celestial Zero-Order Optimizer – `src/optimizer/celestial_zo.nim`**

```nim
import math, times

type
  CelestialZO* = object
    lr*: float64
    epsilon*: float64
    primes*: seq[uint64]

proc newCelestialZO*(): CelestialZO =
  result.lr = 1e-4
  result.epsilon = 1e-5
  result.primes = @[2'u64, 3, 5, 7, 11, 13, 17, 19, 23, 29]

proc julianDay(): float64 =
  let now = now()
  let y = now.year
  let m = now.month.int
  let d = now.monthday

  let a = (14 - m) div 12
  let y_adj = y + 4800 - a
  let m_adj = m + 12 * a - 3

  result = d.float64 + (153*m_adj + 2) div 5 + 365*y_adj +
           y_adj div 4 - y_adj div 100 + y_adj div 400 - 32045

proc step*(self: var CelestialZO, params: var seq[float64], 
           lossFunc: proc(p: seq[float64]): float64) =
  let jd = julianDay()

  for i in 0..<params.len:
    let eps = self.epsilon * self.primes[i mod 10].float64
    let astroOffset = sin(jd * i.float64 * PI / 365.25) * 0.1

    var paramsPlus = params
    paramsPlus[i] += eps * astroOffset
    let fPlus = lossFunc(paramsPlus)

    var paramsMinus = params
    paramsMinus[i] -= eps * astroOffset
    let fMinus = lossFunc(paramsMinus)

    let grad = (fPlus - fMinus) / (2.0 * eps * astroOffset)
    params[i] -= self.lr * grad

# C API export Modal számára
proc celestial_step(params: ptr UncheckedArray[float64], 
                     len: csize_t, lr: float64) {.exportc.} =
  var opt = newCelestialZO()
  opt.lr = lr

  var p = newSeq[float64](len)
  for i in 0..<len:
    p[i] = params[i]

  # Dummy loss function (valódi training loop-ban helyettesítendő)
  proc dummyLoss(x: seq[float64]): float64 =
    result = 0.0
    for v in x:
      result += v * v

  opt.step(p, dummyLoss)

  for i in 0..<len:
    params[i] = p[i]
