### Phase 2: Core Neuromorphic Compute Engine (`src/core/neuromorphic.zig`)

Implement the native compute substrate featuring local Hebbian plasticity, continuous state updates, nested timescale manifolds, Kolmogorov-Discrete-Autoregressive (KDA) gating, and recursive factorized memory:

```zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;

pub const ContinuousNeuron = struct {
    allocator: Allocator,
    synapses: ArrayList(f64),
    membrane_state: f64,
    hebbian_weight: f64,
    timescale_levels: [3]f64,
    continuous_manifold: [512]f64,

    pub fn init(allocator: Allocator, seed: u64) !ContinuousNeuron {
        var prng = DefaultPrng.init(seed);
        var rand = prng.random();
        var syn = ArrayList(f64).init(allocator);
        try syn.ensureTotalCapacity(1024);
        var i: usize = 0;
        while (i < 1024) : (i += 1) {
            syn.appendAssumeCapacity(rand.float(f64) * 0.02 - 0.01);
        }
        return ContinuousNeuron{
            .allocator = allocator,
            .synapses = syn,
            .membrane_state = 0.0,
            .hebbian_weight = 0.05,
            .timescale_levels = .{ 0.0, 0.0, 0.0 },
            .continuous_manifold = mem.zeroes([512]f64),
        };
    }

    pub fn deinit(self: *ContinuousNeuron) void {
        self.synapses.deinit();
    }

    pub fn spike(self: *ContinuousNeuron, input: f64) f64 {
        self.membrane_state += input * self.hebbian_weight;
        if (self.membrane_state >= 1.0) {
            self.membrane_state = 0.0;
            self.hebbian_weight += 0.001 * input;
            return 1.0;
        }
        self.membrane_state *= 0.95;
        return 0.0;
    }

    pub fn updateNestedLevels(self: *ContinuousNeuron, level: usize, delta: f64) void {
        if (level >= 3) return;
        const decay = math.exp(-@as(f64, @floatFromInt(level)) * 0.15);
        self.timescale_levels[level] += delta * decay;
        for (&self.continuous_manifold, 0..) |*elem, i| {
            elem.* += self.timescale_levels[level] * math.sin(self.membrane_state + @as(f64, @floatFromInt(i)) * 0.01227);
        }
    }

    pub fn factorizedMemory(self: *ContinuousNeuron, context: []const f64) f64 {
        if (context.len == 0) return 0.0;
        var sum: f64 = 0.0;
        const limit = @min(context.len, self.synapses.items.len);
        for (context[0..limit], 0..) |val, i| {
            const time_weight = math.exp(-@as(f64, @floatFromInt(i)) * 0.0005);
            sum += val * self.synapses.items[i] * time_weight;
        }
        return sum / @as(f64, @floatFromInt(limit));
    }

    pub fn continuousAutoregressiveFlow(self: *ContinuousNeuron, prev: f64, noise: f64) f64 {
        var phase: f64 = prev + noise;
        var k: usize = 0;
        while (k < 256) : (k += 1) {
            phase += math.cos(2.0 * math.pi * @as(f64, @floatFromInt(k)) * prev / 512.0) * 0.001;
        }
        return phase;
    }

    pub fn kdaGate(self: *ContinuousNeuron, input: f64, decay: f64) f64 {
        return input * (1.0 - decay) + self.membrane_state * decay;
    }

    pub fn recursiveMemory(self: *ContinuousNeuron, depth: usize, base: f64) f64 {
        if (depth == 0) return base;
        const ctx = [_]f64{base};
        return self.recursiveMemory(depth - 1, self.factorizedMemory(&ctx));
    }

    pub fn forward(self: *ContinuousNeuron, inputs: []const f64) f64 {
        var accum: f64 = 0.0;
        for (inputs) |inp| {
            self.membrane_state = self.continuousAutoregressiveFlow(self.membrane_state, math.sin(inp));
            const s = self.spike(inp);
            accum += s;
            self.updateNestedLevels(0, accum);
            self.updateNestedLevels(1, accum * 0.5);
            self.updateNestedLevels(2, accum * 0.1);
        }
        const gated = self.kdaGate(accum, 0.85);
        return self.recursiveMemory(4, gated) + self.factorizedMemory(inputs);
    }

    pub fn backward(self: *ContinuousNeuron, grad: f64, lr: f64) void {
        self.hebbian_weight -= lr * grad * self.membrane_state;
        for (&self.timescale_levels) |*lvl| {
            lvl.* -= lr * grad * lvl.*;
        }
        for (self.synapses.items) |*syn| {
            syn.* -= lr * grad * 0.0001;
        }
    }
};

pub const NeuromorphicLayer = struct {
    allocator: Allocator,
    neurons: []ContinuousNeuron,

    pub fn init(allocator: Allocator, count: usize, seed: u64) !NeuromorphicLayer {
        const neurons = try allocator.alloc(ContinuousNeuron, count);
        for (neurons, 0..) |*n, i| {
            n.* = try ContinuousNeuron.init(allocator, seed +% @as(u64, i));
        }
        return NeuromorphicLayer{
            .allocator = allocator,
            .neurons = neurons,
        };
    }

    pub fn deinit(self: *NeuromorphicLayer) void {
        for (self.neurons) |*n| {
            n.deinit();
        }
        self.allocator.free(self.neurons);
    }

    pub fn forward(self: *NeuromorphicLayer, inputs: []const f64, out: []f64) void {
        std.debug.assert(out.len == self.neurons.len);
        for (self.neurons, 0..) |*neuron, i| {
            out[i] = neuron.forward(inputs);
        }
    }

    pub fn backward(self: *NeuromorphicLayer, grads: []const f64, lr: f64) void {
        for (self.neurons, 0..) |*neuron, i| {
            neuron.backward(grads[i], lr);
        }
    }
};
