### Phase 3: GPU Parallel Tensor Kernels (`src/gpu/factorized_memory.fut`)

Implement the high-throughput continuous state-space factorization and continuous autoregressive flow kernels compiled directly to OpenCL/CUDA SPIR-V:

```futhark
-- High-throughput continuous factorized memory state-space projection
entry factorize_state_space [n][d] (states: [n][d]f64) (factors: [n]f64) (levels: [3]f64) : [n][d]f64 =
  let level_decay = map (\l -> levels[l] * f64.exp(-f64.i64 l * 0.15f64)) (0..<3)
  let level_sum = f64.sum level_decay
  in map (\i ->
    map (\j ->
      states[i, j] * factors[i] * level_sum
    ) (0..<d)
  ) (0..<n)

-- Continuous Autoregressive Flow multi-frequency expansion kernel
entry continuous_ar_kernel [n] (states: [n]f64) (noise: [n]f64) : [n]f64 =
  map (\i ->
    let s = states[i] + noise[i]
    let harmonics = map (\k ->
      f64.cos(2.0f64 * f64.pi * f64.i64 k * s / 512.0f64)
    ) (0..<64)
    in s + (f64.sum harmonics / 64.0f64) * 0.05f64
  ) (0..<n)

-- Discrete-Continuous Kolmogorov Associative Operator
entry kda_associative_scan [n] (inputs: [n]f64) (decay: f64) : [n]f64 =
  scan (\acc x -> acc * decay + x * (1.0f64 - decay)) 0.0f64 inputs
