### Phase 4: Hardware Synthesizable Core (`src/hardware/memristor_crossbar.hs`)

Implement the zero-overhead synthesizable memory-augmented neuromorphic processing array in Clash:

```haskell
{-# LANGUAGE DataKinds, NoImplicitPrelude, TypeOperators #-}
module Main (top_memristor_crossbar) where

import Clash.Prelude

type Rows = 8
type Cols = 8

-- Fixed-point numerical definition for crossbar conductance
type Conductance = SFixed 8 8
type Potential   = SFixed 8 8

-- Memristive conductance integration step
memristorUpdate :: Conductance -> Potential -> Conductance
memristorUpdate cond v =
  let delta = cond * 0.01 + v * 0.005
  in satAdd SatSymmetric cond delta

-- Vector-Matrix Multiplication crossbar unit
crossbarDotProduct :: Vec Rows Potential -> Vec Rows (Vec Cols Conductance) -> Vec Cols Potential
crossbarDotProduct inputs weights =
  let transposed = transpose weights
      colCompute rowWeights = sum (zipWith (*) inputs rowWeights)
  in map colCompute transposed

-- Hardware top entity
top_memristor_crossbar
  :: Clock System
  -> Reset System
  -> Enable System
  -> Signal System (Vec Rows Potential)
  -> Signal System (Vec Cols Potential)
top_memristor_crossbar = exposeClockResetEnable (mealy crossbarState (repeat (repeat 0.1)))
  where
    crossbarState weights inputs = (newWeights, outputs)
      where
        outputs    = crossbarDotProduct inputs weights
        newWeights = map (\row -> zipWith memristorUpdate row inputs) weights
