import Mathlib.Analysis.Calculus.Deriv.Basic
import Mathlib.Topology.MetricSpace.Basic

theorem hebbian_bounded_convergence (w₀ : ℝ) (η : ℝ) (x : ℝ) 
  (hη : 0 < η ∧ η < 1) (hx : |x| ≤ 1) : 
  ∃ M : ℝ, ∀ t : ℕ, |w₀ * (1 - η)^t| ≤ M := by
  use |w₀|
  intro t
  have h1 : |1 - η| < 1 := by
    cases hη with
    | intro hpos hlt =>
      rw [abs_lt]
      constructor
      · linarith
      · linarith
  have h2 : |(1 - η)^t| ≤ 1 := by
    rw [abs_pow]
    exact pow_le_one t (by linarith) (le_of_lt h1)
  rw [abs_mul]
  exact mul_le_of_le_one_right (abs_nonneg w₀) h2
