pragma circom 2.1.6;

template ContinuousStateStep() {
    signal input in_state;
    signal input input_val;
    signal input weight;
    signal output out_state;

    signal intermediate;
    intermediate <== in_state * weight;
    out_state <== intermediate + input_val;
}

template NeuromorphicZKVerifier(n) {
    signal input states[n];
    signal input inputs[n];
    signal input weights[n];
    signal output final_state;

    component steps[n];

    for (var i = 0; i < n; i++) {
        steps[i] = ContinuousStateStep();
        if (i == 0) {
            steps[i].in_state <== 0;
        } else {
            steps[i].in_state <== steps[i-1].out_state;
        }
        steps[i].input_val <== inputs[i];
        steps[i].weight <== weights[i];
    }

    final_state <== steps[n-1].out_state;
}

